package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

// generated is a contract whose files `ergo gen rpc` or `ergo gen cli`
// wrote into a program of packages: the kind (rpc, cli or mcp) and the
// argument of `ergo gen KIND --check`, the contract's package folder and
// its operation type.
type generated struct {
	kind   string
	target string
}

// generatedContracts are the contracts of the program's generated files,
// each once, sorted. A generated file starts with the line "// Code
// generated by ergo gen KIND; DO NOT EDIT." and then "// Contract
// IMPORT.OPTYPE, digest …", whose import path is the module's name and
// the package's folder under the program.
func generatedContracts(p *program) ([]generated, error) {
	module, err := moduleName(filepath.Join(p.dir, "ergo.mod"))
	if err != nil {
		return nil, err
	}
	var out []generated
	for _, source := range p.sources {
		kind, contract, err := generatedHead(source)
		if err != nil {
			return nil, err
		}
		if kind == "" {
			continue
		}
		dot := strings.LastIndex(contract, ".")
		if dot < 0 {
			return nil, fmt.Errorf("%s: the contract %q names no operation type", source, contract)
		}
		path, opType := contract[:dot], contract[dot+1:]
		var dir string
		switch {
		case path == module:
			dir = p.dir
		case strings.HasPrefix(path, module+"/"):
			dir = filepath.Join(p.dir, filepath.FromSlash(strings.TrimPrefix(path, module+"/")))
		default:
			return nil, fmt.Errorf("%s: the contract %q is not a package of the module %s", source, contract, module)
		}
		g := generated{kind: kind, target: dir + "." + opType}
		if !slices.Contains(out, g) {
			out = append(out, g)
		}
	}
	slices.SortFunc(out, func(a, b generated) int { return strings.Compare(a.kind+" "+a.target, b.kind+" "+b.target) })
	return out, nil
}

// generatedHead is the kind and contract of a generated file, or "" for
// a file that ergo gen did not write.
func generatedHead(source string) (kind, contract string, err error) {
	f, err := os.Open(source)
	if err != nil {
		return "", "", err
	}
	defer f.Close()
	lines := bufio.NewScanner(f)
	if !lines.Scan() {
		return "", "", lines.Err()
	}
	rest, ok := strings.CutPrefix(lines.Text(), "// Code generated by ergo gen ")
	if !ok {
		return "", "", nil
	}
	kind, ok = strings.CutSuffix(rest, "; DO NOT EDIT.")
	if !ok || !lines.Scan() {
		return "", "", fmt.Errorf("%s: a generated file names its contract on its second line", source)
	}
	contract, ok = strings.CutPrefix(lines.Text(), "// Contract ")
	if !ok {
		return "", "", fmt.Errorf("%s: a generated file names its contract on its second line", source)
	}
	contract, _, _ = strings.Cut(contract, ",")
	return kind, contract, nil
}

// moduleName is the name an ergo.mod declares.
func moduleName(file string) (string, error) {
	text, err := os.ReadFile(file)
	if err != nil {
		return "", err
	}
	for _, line := range strings.Split(string(text), "\n") {
		if name, ok := strings.CutPrefix(strings.TrimSpace(line), "module "); ok {
			return strings.TrimSpace(name), nil
		}
	}
	return "", fmt.Errorf("%s declares no module", file)
}

// genProgram runs `ergo gen KIND --check` on each contract of the
// program's generated files: a file that differs from what the contract
// generates now (a stale file) fails the program.
func (r *runner) genProgram(p *program) bool {
	if !p.module {
		return true
	}
	contracts, err := generatedContracts(p)
	if err != nil {
		fmt.Fprintf(r.out, "FAIL %s: gen: %v\n", p.name, err)
		r.fail(p.name + ": gen")
		return false
	}
	passed := true
	for _, g := range contracts {
		leg := "gen " + g.kind + " " + strings.TrimPrefix(g.target, p.dir+string(filepath.Separator))
		if o, err := r.tool(0, "gen", g.kind, "--check", g.target); err != nil || !o.passed() {
			r.toolFailed(p, leg, o, err)
			passed = false
		}
	}
	return passed
}
